// Turns wasm2js output into a self-contained ES module whose `env` imports
// are bound to Math.* at runtime (the browser cannot resolve a bare 'env').
import { readFileSync, writeFileSync } from 'node:fs';

const [, , inFile, outFile] = process.argv;
let js = readFileSync(inFile, 'utf8');
const header =
  '// AUTO-GENERATED by core/Makefile (wasm2js) — JS fallback of opensky_core.wasm.\n' +
  'const env = { sin: Math.sin, cos: Math.cos, tan: Math.tan, asin: Math.asin, acos: Math.acos,\n' +
  '  atan2: Math.atan2, exp: Math.exp, log: Math.log, pow: Math.pow };\n';
js = js.replace(/import\s*\*\s*as\s+env\s+from\s+['"]env['"];?\n?/g, '');
js = js.replace(/import\s*\{([^}]*)\}\s*from\s*['"]env['"];?\n?/g, (_, names) =>
  names
    .split(',')
    .map((n) => n.trim())
    .filter(Boolean)
    .map((n) => {
      const [a, b] = n.split(/\s+as\s+/);
      return `const ${b || a} = env.${a};\n`;
    })
    .join(''),
);
writeFileSync(outFile, header + js);
console.log(`wrote ${outFile}`);
